_S10 = [("Reporter", "Paano gamitin ang Project Noah?", "How to use Project Noah?"), ("Reporter", "Ang una po nating dapat gawin ay buksan ang internet browser at i-type ang noah.dost.gov.ph.", "The first thing we should do is open the internet browser and type noah.dost.gov.ph."), ("Reporter", "Hintayin hanggang lumabas ang project Noah website.", "Wait until the Project Noah website appears."), ("Reporter", "Marami po tayong makikita dito na mga tabs, kulay asul at mga tabs po sa baba niyan, mapa ng Pilipinas, ang karagatan sa Pilipinas, ang twitter feeds ng DOST, pag-asa at climate x na isang bahagi din po ng project Noah.", "We will see many tabs here, blue ones and tabs below them: the map of the Philippines, the seas of the Philippines, the Twitter feeds of DOST and PAGASA, and Climate X, which is also a part of Project Noah."), ("Reporter", "Pero ang unang bibigyan natin ng pansin at bubuksan ay ang MPSAT or Multi-transport Satellite na galing sa Japan na nagbibigay po sa atin sa kalawakan ng pananaw kung ano ang nangyayari sa Pilipinas at sa mga paligid nitong karagatan.", "But the first thing we will give attention to and open is the MPSAT or Multi-transport Satellite from Japan, which gives us a view from space of what is happening in the Philippines and its surrounding seas."), ("Reporter", "Sa ngayon po, kailangan nating tingnan ang oras kung ito ay up-to-date at makikita natin ngayon na mayroong sama ng panahon na namumuo dito sa dagat-Pasipiko.", "For now, we need to check the time to see if it is up to date, and we will see now that there is a bad weather system forming here in the Pacific Ocean."), ("Reporter", "At dito po sa dagat-Pasipiko merong umiikot o sumisirko na mga kaulapan na nakikita natin bilang kulay-pula, kulay-dilaw at kulay-puti.", "And here in the Pacific Ocean there are swirling or rotating cloud formations that we see as red, yellow and white."), ("Reporter", "Kung gusto po nating malaman kung ang sama ng panahon ay pumasok na sa Philippine Area of Responsibility, kailangan pumasok tayo sa weather outlook, PAG-ASA cyclone update at lalabas po ang puting linya na nagsasabi kung nasaan po ang PAR o ang Philippine Area of Responsibility.", "If we want to know whether the bad weather has entered the Philippine Area of Responsibility, we need to go into the weather outlook, PAG-ASA cyclone update, and the white line will appear that tells where the PAR or the Philippine Area of Responsibility is."), ("Reporter", "Sa ngayon ang sama ng panahon ay nandun pa sa labas ng PAR.", "For now the bad weather is still outside the PAR.")]
_K10 = [["1. Open the internet browser and type noah.dost.gov.ph and wait until the Project Noah website appears.", "There are different tabs below on the Project Noah website. The tabs include the map of the Philippines, the Philippine seas, the Twitter feeds of DOST and PAG-ASA, and Climate X. Climate is also part of Project Noah."], ["2. Open the MPSAT or Multi-transport Satellite.", "The MPSAT is from Japan. The MPSAT gives information about space and the situation of the Philippines and its surrounding bodies of water."], ["3. Check the time if it is updated.", "There is a low-pressure area building in the Pacific Ocean. In the areas of the Pacific Ocean there are swirling and rotating cloud formations seen in red, yellow and white."], ["4. Open the weather outlook, the PAG-ASA cyclone update, to check if there is a low-pressure area (LPA) in the Philippine Area of Responsibility (PAR).", "The white line you will see tells you where the PAR is located. Currently, the low-pressure area is still outside the PAR."]]
